(()=>{
const byId=id=>document.getElementById(id),results=byId('reader-results'),verses=byId('reader-verses'),search=byId('reader-search'),status=byId('reader-status');let mode='surah',selected={mode:'surah',number:1},request=0,controller,size=48,last={};try{last=JSON.parse(localStorage.getItem('adhan-reading')||'{}');size=Math.min(64,Math.max(32,(last.styleVersion===2?Number(last.size):48)||48));if(['surah','juz'].includes(last.mode)&&Number.isInteger(last.number)&&last.number>=1&&last.number<=(last.mode==='surah'?114:30)){mode=last.mode;selected={mode,number:last.number}}}catch{}
function normalize(text){return String(text).normalize('NFD').replace(/[\u0300-\u036f\u0610-\u061a\u064b-\u065f\u0670\u06d6-\u06ed\u0640]/g,'').replace(/[أإآٱ]/g,'ا').replace(/ى/g,'ي').replace(/[٠-٩]/g,c=>'٠١٢٣٤٥٦٧٨٩'.indexOf(c)).toLowerCase().replace(/[^a-z0-9\u0621-\u064a]/g,'')}
function save(){try{localStorage.setItem('adhan-reading',JSON.stringify({...selected,size,styleVersion:2}))}catch{}}
function applySize(){verses.style.setProperty('--arabic-size',size+'px');byId('text-smaller').disabled=size<=32;byId('text-larger').disabled=size>=64}
function list(){results.replaceChildren();const term=normalize(search.value),items=mode==='surah'?readerCatalog.surahs:readerCatalog.juz;const matches=items.filter(s=>{const query=mode==='surah'?`${s.englishName} ${s.englishNameTranslation} ${s.name} ${typeof quranCatalog!=='undefined'?quranCatalog.surahs.find(a=>a.id===s.number)?.name||'':''}`:`juz ${s.number} ${s.start} ${s.arabic.join(' ')}`;return !term||(/^\d+$/.test(term)?s.number===Number(term):normalize(query).includes(term))});for(const item of matches){const button=document.createElement('button');button.type='button';button.className='reader-result';button.setAttribute('aria-pressed',String(selected.mode===mode&&selected.number===item.number));const top=document.createElement('span');top.textContent=mode==='surah'?`${item.number}. ${item.englishName}`:`Juz ${item.number}`;const sub=document.createElement('small');sub.textContent=mode==='surah'?item.name:item.start;if(mode==='surah'){sub.lang='ar';sub.dir='rtl'}button.append(top,sub);button.onclick=()=>open(mode,item.number);results.append(button)}if(!matches.length){const p=document.createElement('p');p.className='fine';p.textContent='No matches. Try a name or a number'+(mode==='surah'?' from 1 to 114.':' from 1 to 30.');results.append(p)}}
function updateMode(){byId('read-surahs').setAttribute('aria-pressed',String(mode==='surah'));byId('read-juz').setAttribute('aria-pressed',String(mode==='juz'));search.placeholder=mode==='surah'?'Search surahs by Arabic / English name or number…':'Search juz by number or starting surah…';list()}
function cacheRead(key){try{return JSON.parse(localStorage.getItem('adhan-reader-cache')||'{}')[key]}catch{return null}}
function cacheWrite(key,value){try{let cache=JSON.parse(localStorage.getItem('adhan-reader-cache')||'{}');delete cache[key];cache[key]=value;const keys=Object.keys(cache);while(keys.length>3)delete cache[keys.shift()];localStorage.setItem('adhan-reader-cache',JSON.stringify(cache))}catch{}}
function render(payload){const fragment=document.createDocumentFragment();let previousSurah=null;for(const ayah of payload.ayahs){const surah=selected.mode==='surah'?readerCatalog.surahs.find(s=>s.number===selected.number):ayah.surah;if(previousSurah!==surah.number){const h=document.createElement('h4');h.className='verse-surah';h.textContent=surah.name;h.lang='ar';h.dir='rtl';const english=document.createElement('p');english.className='verse-surah-english';english.textContent=`${surah.number}. ${surah.englishName}`;fragment.append(h,english);previousSurah=surah.number}const row=document.createElement('div');row.className='ayah-row';const text=document.createElement('p');text.className='arabic-ayah';text.lang='ar';text.dir='rtl';text.textContent=ayah.text;const ref=document.createElement('span');ref.className='ayah-reference';ref.textContent=String(ayah.numberInSurah);ref.setAttribute('aria-label',`Surah ${surah.number}, ayah ${ayah.numberInSurah}, juz ${ayah.juz}`);row.append(text,ref);fragment.append(row)}verses.replaceChildren(fragment);status.textContent=`${payload.ayahs.length} ayahs · Bold Uthmani Arabic`;}
async function open(nextMode,number){selected={mode:nextMode,number};mode=nextMode;save();updateMode();const id=++request;controller?.abort();controller=new AbortController();const key=`${nextMode}-${number}`,cached=cacheRead(key);verses.replaceChildren();verses.setAttribute('aria-busy','true');byId('reader-retry').hidden=true;const surah=readerCatalog.surahs.find(s=>s.number===number);byId('reading-title').textContent=nextMode==='surah'?`${number}. ${surah.englishName}`:`Juz ${number}`;byId('reading-subtitle').textContent=nextMode==='surah'?`${surah.name} · ${surah.englishNameTranslation}`:readerCatalog.juz[number-1].start;byId('reader-prev').disabled=number===1;byId('reader-next').disabled=number===(mode==='surah'?114:30);byId('reader-prev').textContent='← Previous '+nextMode;byId('reader-next').textContent='Next '+nextMode+' →';if(cached){render(cached);status.textContent+=' · Saved offline';verses.setAttribute('aria-busy','false');return}status.textContent='Loading Arabic text…';const timeout=setTimeout(()=>controller?.abort(),20000);try{const res=await fetch(`https://api.alquran.cloud/v1/${nextMode}/${number}/quran-uthmani`,{signal:controller.signal});if(!res.ok)throw Error();const json=await res.json();if(json.code!==200||!Array.isArray(json.data?.ayahs)||!json.data.ayahs.length)throw Error();if(id!==request)return;render(json.data);cacheWrite(key,json.data)}catch{if(id!==request)return;status.textContent='Could not load this section. Check your connection and try again.';byId('reader-retry').hidden=false}finally{clearTimeout(timeout);if(id===request)verses.setAttribute('aria-busy','false')}}
search.oninput=list;byId('read-surahs').onclick=()=>{mode='surah';search.value='';updateMode()};byId('read-juz').onclick=()=>{mode='juz';search.value='';updateMode()};byId('reader-prev').onclick=()=>{if(selected.number>1)open(selected.mode,selected.number-1)};byId('reader-next').onclick=()=>{if(selected.number<(selected.mode==='surah'?114:30))open(selected.mode,selected.number+1)};byId('reader-retry').onclick=()=>open(selected.mode,selected.number);byId('text-smaller').onclick=()=>{size=Math.max(32,size-2);applySize();save()};byId('text-larger').onclick=()=>{size=Math.min(64,size+2);applySize();save()};applySize();updateMode();open(selected.mode,selected.number);
})();
